// Appends Infection Control ids 151-184 + Nail Structure & Analysis ids 185-200
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'
const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

const icT=`"Infection Control & Sanitation"`, icTes=`"Control de Infecciones y Saneamiento"`, icPt=`"Infection Control"`, icPtes=`"Control de Infecciones"`
const nsT=`"Nail Structure & Analysis"`, nsTes=`"Estructura y Análisis de Uñas"`, nsPt=`"Nail Structure & Analysis"`, nsPtes=`"Estructura y Análisis de Uñas"`

function fmt(q, t, tes, pt, ptes) {
  return `  { id: ${q.id}, topic: ${t}, topic_es: ${tes}, psi_topic: ${pt}, psi_topic_es: ${ptes}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const IC = [
  { id: 151, question: "A client intake form in an esthetics establishment should include questions about:", question_es: "Un formulario de admisión del cliente en un establecimiento de estética debe incluir preguntas sobre:", options: ["Current medications, skin conditions, allergies, recent procedures, and any contagious conditions — this information helps the esthetician identify contraindications and modify services to protect both the client and the esthetician", "Only the client's name, address, and method of payment", "The client's complete medical history including all diagnoses since childhood", "Only the specific esthetics service the client wishes to receive"], options_es: ["Medicamentos actuales, condiciones cutáneas, alergias, procedimientos recientes y cualquier condición contagiosa — esta información ayuda al esteticista a identificar contraindicaciones y modificar los servicios para proteger tanto al cliente como al esteticista", "Solo el nombre, la dirección y el método de pago del cliente", "El historial médico completo del cliente incluyendo todos los diagnósticos desde la infancia", "Solo el servicio de estética específico que el cliente desea recibir"], correct: 0, explanation: "The client intake form (also called the consultation form or health history form) is a fundamental infection control and safety tool. It identifies contraindications that could make a service unsafe, and discloses allergies that could cause adverse reactions. It must be updated periodically as client health status changes." },
  { id: 152, question: "EPA registration numbers on disinfectant product labels are important in an esthetics establishment because:", question_es: "Los números de registro de la EPA en las etiquetas de los productos desinfectantes son importantes en un establecimiento de estética porque:", options: ["The EPA registration number confirms the product has been reviewed and registered by the EPA for the efficacy claims stated on the label — using registered products ensures the esthetician is using a product whose claims are government-verified", "The EPA registration number is only important for products sold in hospitals — esthetics establishments are exempt from EPA registration requirements", "The EPA number indicates the product is safe to consume if accidentally ingested", "EPA registration only applies to disinfectants used on surfaces, not on implements"], options_es: ["El número de registro de la EPA confirma que el producto ha sido revisado y registrado por la EPA para las reclamaciones de eficacia declaradas en la etiqueta — usar productos registrados garantiza que el esteticista está usando un producto cuyas reclamaciones están verificadas por el gobierno", "El número de registro de la EPA solo es importante para los productos vendidos en hospitales — los establecimientos de estética están exentos de los requisitos de registro de la EPA", "El número de EPA indica que el producto es seguro para consumir si se ingiere accidentalmente", "El registro de la EPA solo aplica a los desinfectantes usados en superficies, no en implementos"], correct: 0, explanation: "EPA registration under FIFRA (Federal Insecticide, Fungicide, and Rodenticide Act) means the EPA has reviewed and registered the product's efficacy and safety claims. When selecting disinfectants for esthetics use, always choose EPA-registered products and use them as directed by the label — this is both legally and scientifically sound practice." },
  { id: 153, question: "A Safety Data Sheet (SDS) for a disinfectant product used in an esthetics establishment must:", question_es: "Una Hoja de Datos de Seguridad (SDS) para un producto desinfectante usado en un establecimiento de estética debe:", options: ["Be maintained on file and accessible to all employees — SDS sheets provide information on chemical hazards, safe handling, first aid for exposure, and emergency procedures required by OSHA's Hazard Communication Standard", "Be kept confidential and only accessible to the salon owner", "Be replaced with a summarized fact sheet — SDS documents are too technical for esthetics employees", "Only be obtained if an employee is actually injured by the product"], options_es: ["Mantenerse archivada y accesible para todos los empleados — las hojas de SDS proporcionan información sobre peligros químicos, manejo seguro, primeros auxilios para la exposición y procedimientos de emergencia requeridos por el Estándar de Comunicación de Peligros de OSHA", "Mantenerse confidencial y solo accesible para el propietario del salón", "Reemplazarse con una hoja de datos resumida — los documentos SDS son demasiado técnicos para los empleados de estética", "Solo obtenerse si un empleado resulta lesionado por el producto"], correct: 0, explanation: "OSHA's Hazard Communication Standard (HazCom, or 'Right to Know' law) requires that SDS (formerly MSDS) documents for all hazardous chemicals be readily accessible to employees during their work shift. SDS provide 16 standardized sections including hazard identification, first aid, fire-fighting measures, and exposure limits." },
  { id: 154, question: "UV (ultraviolet) sanitizing cabinets used in some esthetics establishments:", question_es: "Los gabinetes de saneamiento UV (ultravioleta) usados en algunos establecimientos de estética:", options: ["Are useful for storing clean, already-disinfected implements but are NOT a substitute for proper cleaning and disinfection — UV light cannot adequately penetrate surfaces, shadowed areas, or implements that have not already been cleaned", "Provide sterilization equivalent to autoclaving — any implement placed in the UV cabinet for 30 minutes is sterile", "Replace the need for chemical disinfectants entirely for all implement types", "Are specifically required by Texas TDLR for all esthetics establishments as the primary implement storage method"], options_es: ["Son útiles para almacenar implementos limpios y ya desinfectados pero NO son un sustituto de la limpieza y desinfección adecuadas — la luz UV no puede penetrar adecuadamente las superficies, las áreas sombreadas o los implementos que aún no han sido limpiados", "Proporcionan esterilización equivalente al autoclave — cualquier implemento colocado en el gabinete UV durante 30 minutos es estéril", "Reemplazan la necesidad de desinfectantes químicos por completo para todos los tipos de implementos", "Son específicamente requeridos por Texas TDLR para todos los establecimientos de estética como el método principal de almacenamiento de implementos"], correct: 0, explanation: "UV cabinets emit ultraviolet C (UVC) light that can kill surface microorganisms, but UV light cannot penetrate surfaces or reach shadowed areas of implements. They do NOT sterilize and are NOT a substitute for chemical disinfection. Legitimate use: storing clean pre-disinfected implements to maintain their clean status until use." },
  { id: 155, question: "Biofilm formation on surfaces and implements in an esthetics establishment is a concern because:", question_es: "La formación de biopelícula en superficies e implementos en un establecimiento de estética es una preocupación porque:", options: ["Biofilm (a community of microorganisms embedded in a self-produced matrix) is significantly more resistant to disinfectants than individual planktonic bacteria — proper mechanical cleaning before disinfection is essential to disrupt and remove biofilm", "Biofilm is only a concern in hospital environments — it does not form in esthetics settings", "Biofilm is only cosmetically unappealing and has no effect on disinfectant efficacy", "Standard disinfectants are completely effective against biofilm without any prior mechanical cleaning step"], options_es: ["La biopelícula (una comunidad de microorganismos incrustados en una matriz autoproducida) es significativamente más resistente a los desinfectantes que las bacterias planctónicas individuales — la limpieza mecánica adecuada antes de la desinfección es esencial para interrumpir y eliminar la biopelícula", "La biopelícula solo es una preocupación en entornos hospitalarios — no se forma en los entornos de estética", "La biopelícula solo es estéticamente desagradable y no tiene ningún efecto en la eficacia del desinfectante", "Los desinfectantes estándar son completamente efectivos contra la biopelícula sin ningún paso previo de limpieza mecánica"], correct: 0, explanation: "Biofilm forms on inadequately cleaned surfaces (facial beds, drains, equipment) where microbial communities establish themselves in a protective matrix. Biofilm can be 10–1000× more resistant to disinfection than planktonic (free-floating) bacteria. This is why the mechanical cleaning step before disinfection is non-negotiable — you cannot disinfect a dirty surface." },
  { id: 156, question: "Herpes simplex virus (HSV-1, causing cold sores/fever blisters) as a contraindication in esthetics means:", question_es: "El virus del herpes simple (HSV-1, que causa herpes labial/ampollas febriles) como contraindicación en la estética significa:", options: ["Active cold sore lesions on or near the face are a contraindication for facial services — the esthetician risks spreading the virus to other areas of the face or self-inoculation, and the service would cause pain over active lesions", "Cold sores are cosmetic blemishes only and have no bearing on service safety — services can proceed normally", "Only clients with genital herpes must disclose their condition — oral herpes (cold sores) is never a contraindication for facial services", "Cold sores must be treated with steam and extractions during the facial to accelerate healing"], options_es: ["Las lesiones activas de herpes labial en o cerca del rostro son una contraindicación para los servicios faciales — el esteticista arriesga diseminar el virus a otras áreas del rostro o auto-inocularse, y el servicio causaría dolor sobre las lesiones activas", "Los herpes labiales son solo imperfecciones cosméticas y no tienen ninguna relación con la seguridad del servicio — los servicios pueden proceder normalmente", "Solo los clientes con herpes genital deben revelar su condición — el herpes oral (herpes labial) nunca es una contraindicación para los servicios faciales", "Los herpes labiales deben tratarse con vapor y extracciones durante el facial para acelerar la curación"], correct: 0, explanation: "HSV-1 causes highly contagious oral herpes (cold sores). The virus can be spread by direct contact and on fomites. Active lesions indicate the client is in a shedding phase with high viral load. Facial massage, steam, and extractions over active lesions would be painful and could spread the virus. Service must be postponed until lesions are fully healed." },
  { id: 157, question: "Tinea faciei (ringworm of the face) encountered during a client consultation requires:", question_es: "La tiña facial (tiña del rostro) encontrada durante una consulta del cliente requiere:", options: ["Declining the facial service and referring the client to a physician for treatment — tinea faciei is a contagious fungal infection that can be spread by direct contact and through contaminated implements", "Applying antifungal cream during the facial service to treat the infection while providing the service", "Proceeding with the service but avoiding direct contact with the affected area", "Documenting the condition and informing TDLR immediately"], options_es: ["Rechazar el servicio facial y derivar al cliente a un médico para tratamiento — la tiña facial es una infección fúngica contagiosa que puede propagarse por contacto directo y a través de implementos contaminados", "Aplicar crema antimicótica durante el servicio facial para tratar la infección mientras se proporciona el servicio", "Proceder con el servicio pero evitar el contacto directo con el área afectada", "Documentar la condición e informar a TDLR de inmediato"], correct: 0, explanation: "Tinea faciei (facial ringworm) is a contagious dermatophyte fungal infection. Active fungal infections of the face are a contraindication for esthetics services — service would risk spreading the infection to other facial areas and to the esthetician through contaminated implements. Referral to a dermatologist for antifungal medication is required." },
  { id: 158, question: "The chain of infection can be broken in an esthetics establishment primarily by:", question_es: "La cadena de infección puede romperse en un establecimiento de estética principalmente por:", options: ["Eliminating or disrupting the mode of transmission — proper implement disinfection, hand hygiene, single-use items, clean linens, and surface disinfection interrupt the path from infectious agent to susceptible host", "Identifying and excluding all clients who are currently ill — this is the only effective break in the chain", "Using prescription-strength antimicrobials to sterilize all surfaces and implements daily", "Relying on clients to maintain their own infection control at home before and after services"], options_es: ["Eliminar o interrumpir el modo de transmisión — la desinfección adecuada de implementos, la higiene de manos, los artículos de uso único, la ropa de cama limpia y la desinfección de superficies interrumpen el camino desde el agente infeccioso hasta el huésped susceptible", "Identificar y excluir a todos los clientes que están actualmente enfermos — esta es la única ruptura efectiva en la cadena", "Usar antimicrobianos de fuerza de prescripción para esterilizar todas las superficies e implementos diariamente", "Depender de los clientes para que mantengan su propio control de infecciones en casa antes y después de los servicios"], correct: 0, explanation: "The chain of infection: infectious agent → reservoir → portal of exit → mode of transmission → portal of entry → susceptible host. Breaking any link stops infection. In esthetics, breaking the mode of transmission (disinfection, single-use items, hand hygiene, PPE) is the primary and most practical intervention for preventing pathogen transfer between clients." },
  { id: 159, question: "Quaternary ammonium compounds (quats) used as disinfectants in esthetics lose efficacy when:", question_es: "Los compuestos de amonio cuaternario (cuaternarios) usados como desinfectantes en la estética pierden eficacia cuando:", options: ["Diluted improperly (too concentrated or too dilute), used in hard water without distilled water adjustment, exposed to organic material buildup (dirty implements), or when the solution is too old — all of these require fresh solution preparation per manufacturer instructions", "The temperature of the solution drops below room temperature", "The solution contacts metal implements — quats are incompatible with all metals", "The disinfectant container is opened more than once — quats must be used from sealed, single-use containers only"], options_es: ["Diluidos incorrectamente (demasiado concentrados o demasiado diluidos), usados en agua dura sin ajuste de agua destilada, expuestos a la acumulación de materia orgánica (implementos sucios) o cuando la solución es demasiado vieja — todo esto requiere una preparación de solución fresca según las instrucciones del fabricante", "La temperatura de la solución cae por debajo de la temperatura ambiente", "La solución contacta implementos de metal — los cuaternarios son incompatibles con todos los metales", "El recipiente del desinfectante se abre más de una vez — los cuaternarios solo deben usarse de recipientes sellados de uso único"], correct: 0, explanation: "Quaternary ammonium (quat) efficacy is reduced by: (1) hard water minerals (use distilled water), (2) organic matter buildup (dirty implements must be cleaned first), (3) improper dilution (too high or too low concentration), and (4) aging solution. Always prepare fresh quat solution per manufacturer instructions and change it at specified intervals." },
  { id: 160, question: "When performing a chemical exfoliation (chemical peel) service, infection control requires:", question_es: "Al realizar un servicio de exfoliación química (peel químico), el control de infecciones requiere:", options: ["Reviewing the client's health history for contraindications (active lesions, recent retinoid use, immunosuppression), wearing appropriate PPE (gloves, eye protection), using sterile/single-use applicators, and following post-service protocols for disinfecting all surfaces and implements", "Only wearing gloves — no other infection control measures are needed for chemical peel services", "Sterilizing the client's face with antiseptic before applying any chemical peel agents", "Applying the peel with bare, freshly washed hands — gloves can cause chemical to pool unevenly"], options_es: ["Revisar el historial de salud del cliente para detectar contraindicaciones (lesiones activas, uso reciente de retinoides, inmunosupresión), usar EPP apropiado (guantes, protección para los ojos), usar aplicadores estériles/de uso único y seguir los protocolos post-servicio para desinfectar todas las superficies e implementos", "Solo usar guantes — no se necesitan otras medidas de control de infecciones para los servicios de peel químico", "Esterilizar el rostro del cliente con antiséptico antes de aplicar cualquier agente de peel químico", "Aplicar el peel con manos desnudas, recién lavadas — los guantes pueden hacer que el químico se acumule de manera desigual"], correct: 0, explanation: "Chemical peel services involve applying acids or other chemical agents that compromise the skin's barrier. This increases infection risk for the client. Infection control essentials: client health screening, PPE (gloves and eye protection for the esthetician), single-use applicators, and thorough surface/implement disinfection post-service." },
  { id: 161, question: "When a client presents with open acne lesions (pustules, papules with surface breaks) during a facial appointment:", question_es: "Cuando un cliente presenta lesiones de acné abiertas (pústulas, pápulas con roturas superficiales) durante una cita facial:", options: ["The esthetician must avoid aggressive manipulation of open lesions, use clean implements and single-use materials for each area contacted, and avoid spreading bacteria from lesion areas to unaffected skin — some active acne contraindications may preclude certain services altogether", "Active acne is an ideal condition for extraction and manipulation to clear all lesions in one session", "Extractions should be performed on all visible pustules regardless of inflammation level — this is the purpose of the facial", "Open acne lesions require no special protocol — standard infection control for any facial applies equally"], options_es: ["El esteticista debe evitar la manipulación agresiva de las lesiones abiertas, usar implementos limpios y materiales de uso único para cada área contactada y evitar diseminar bacterias de las áreas de lesión a la piel sin afectación — algunas contraindicaciones de acné activo pueden impedir ciertos servicios por completo", "El acné activo es una condición ideal para la extracción y manipulación para limpiar todas las lesiones en una sesión", "Las extracciones deben realizarse en todas las pústulas visibles independientemente del nivel de inflamación — este es el propósito del facial", "Las lesiones de acné abiertas no requieren ningún protocolo especial — el control de infecciones estándar para cualquier facial aplica igualmente"], correct: 0, explanation: "Open acne lesions are portals of infection entry and exit. Aggressive manipulation spreads Cutibacterium acnes bacteria to surrounding follicles and can introduce other bacteria into lesions. Infected implements can spread bacteria between lesions. Protocol: gentle technique, single-use materials for lesion areas, avoid extracting highly inflamed pustules." },
  { id: 162, question: "A magnifying lamp used in esthetics services should be disinfected:", question_es: "Una lámpara de aumento usada en los servicios de estética debe desinfectarse:", options: ["Between each client — all contact surfaces (lamp arm, adjustment knobs, base, face shield/lens exterior) that may have been touched during the service should be wiped with an EPA-registered disinfectant", "Only at the end of each workday — magnifying lamps do not contact the client's skin directly", "Only the glass lens requires disinfection — the frame and arm are non-critical and never need disinfecting", "Weekly — the lamp generates UV light that self-disinfects all surfaces during operation"], options_es: ["Entre cada cliente — todas las superficies de contacto (brazo de la lámpara, perillas de ajuste, base, escudo facial/exterior del lente) que pueden haber sido tocadas durante el servicio deben limpiarse con un desinfectante registrado por la EPA", "Solo al final de cada día de trabajo — las lámparas de aumento no contactan directamente la piel del cliente", "Solo el lente de vidrio requiere desinfección — el marco y el brazo son no críticos y nunca necesitan desinfección", "Semanalmente — la lámpara genera luz UV que auto-desinfecta todas las superficies durante su operación"], correct: 0, explanation: "All equipment surfaces touched during client services (lamp arm, knobs, switches) are potentially contaminated. Even though the lamp lens doesn't contact the client's skin, the surfaces handled by the esthetician during the service can harbor pathogens. Between-client disinfection of all touched equipment surfaces is required." },
  { id: 163, question: "Respiratory hygiene and cough etiquette in an esthetics establishment protects against:", question_es: "La higiene respiratoria y la etiqueta al toser en un establecimiento de estética protege contra:", options: ["Transmission of respiratory pathogens (influenza, respiratory viruses, bacteria) via droplets produced during coughing, sneezing, or talking — both clients and estheticians can be sources and both can be protected by proper respiratory etiquette and mask use", "Only protecting clients from esthetician respiratory infections — estheticians are immune to client respiratory illnesses by professional exposure", "Legal liability only — respiratory hygiene has no actual effect on pathogen transmission in esthetics", "Only airborne pathogens — droplet-spread organisms are not a concern in esthetics establishments"], options_es: ["Transmisión de patógenos respiratorios (influenza, virus respiratorios, bacterias) a través de gotitas producidas durante la tos, los estornudos o al hablar — tanto los clientes como los esteticistas pueden ser fuentes y ambos pueden ser protegidos por la etiqueta respiratoria adecuada y el uso de mascarillas", "Solo proteger a los clientes de las infecciones respiratorias del esteticista — los esteticistas son inmunes a las enfermedades respiratorias de los clientes por exposición profesional", "Solo responsabilidad legal — la higiene respiratoria no tiene ningún efecto real en la transmisión de patógenos en los establecimientos de estética", "Solo patógenos aéreos — los organismos propagados por gotitas no son una preocupación en los establecimientos de estética"], correct: 0, explanation: "Esthetics services are performed in close proximity to the client's face, making respiratory droplet transmission a real risk in both directions. Covering coughs and sneezes (with tissue or elbow), disposing of used tissues, and hand hygiene after respiratory contact protect against droplet-spread pathogens including influenza and respiratory bacteria." },
  { id: 164, question: "An esthetician performing facial waxing must discard which items immediately after each client?", question_es: "Un esteticista que realiza depilación facial debe desechar cuáles artículos inmediatamente después de cada cliente?", options: ["All single-use wax applicators (wooden sticks/spatulas), wax strips used during the service, any cotton rounds or gauze used, gloves — all porous or single-use items that contacted the client are discarded; the wax pot and metal wax heater are cleaned and disinfected", "Only the wax strips — wooden applicators can be cleaned with disinfectant and reused", "Only visible hair debris — other waxing items are not single-use and can be sanitized for reuse", "Nothing from a waxing service requires immediate discard — all items can be cleaned and autoclaved for reuse"], options_es: ["Todos los aplicadores de cera de uso único (palitos de madera/espátulas), las tiras de cera usadas durante el servicio, cualquier almohadilla de algodón o gasa usada, los guantes — todos los artículos porosos o de uso único que contactaron al cliente se descartan; el pote de cera y el calentador de cera de metal se limpian y desinfectan", "Solo las tiras de cera — los aplicadores de madera se pueden limpiar con desinfectante y reutilizar", "Solo los residuos de cabello visibles — otros artículos de depilación no son de uso único y pueden sanearse para reutilizarlos", "Nada de un servicio de depilación requiere desechar de inmediato — todos los artículos pueden limpiarse y esterilizarse en autoclave para reutilizarlos"], correct: 0, explanation: "Waxing generates many single-use items: wooden spatulas (porous, cannot be disinfected), used wax strips (contaminated), cotton rounds/gauze, gloves. These must all be discarded after each client. The metal wax pot, heater base, and any reusable metal items should be cleaned and disinfected. Wax in a clean pot remains usable if no double-dipping occurred." },
  { id: 165, question: "The principle of 'standard precautions' in esthetics means:", question_es: "El principio de 'precauciones estándar' en la estética significa:", options: ["Treating ALL clients' blood, body fluids, and non-intact skin as potentially infectious regardless of the client's known health status — standard precautions protect both the esthetician and all clients without requiring knowledge of specific diagnoses", "Only taking special precautions when a client has disclosed a known infectious condition", "Wearing full surgical gowns and face shields for every esthetics service", "Applying standard precautions only during services that involve needles — routine facials require no precautions"], options_es: ["Tratar TODA la sangre, los fluidos corporales y la piel no intacta de todos los clientes como potencialmente infecciosos independientemente del estado de salud conocido del cliente — las precauciones estándar protegen tanto al esteticista como a todos los clientes sin requerir conocimiento de diagnósticos específicos", "Solo tomar precauciones especiales cuando un cliente ha revelado una condición infecciosa conocida", "Usar batas quirúrgicas completas y protectores faciales para cada servicio de estética", "Aplicar precauciones estándar solo durante los servicios que implican agujas — los faciales de rutina no requieren precauciones"], correct: 0, explanation: "Standard precautions (evolved from 'universal precautions') are based on the assumption that any client may be carrying an infectious agent, whether they know it or not. Rather than waiting for a disclosure, standard precautions apply the same protective measures to every client. This eliminates the problem of unknown carriers and removes the need for clients to disclose status." },
  { id: 166, question: "Proper documentation of sanitation procedures in an esthetics establishment serves which key purpose during a TDLR inspection?", question_es: "La documentación adecuada de los procedimientos de saneamiento en un establecimiento de estética sirve cuál propósito clave durante una inspección de TDLR?", options: ["Provides evidence that required sanitation protocols are actually being followed consistently — inspectors can review logs to verify compliance with disinfection procedures, product use records, and staff training, rather than relying solely on observation during inspection", "Documentation is only required for medical facilities — esthetics establishments are exempt from TDLR documentation requirements", "Serves only as marketing material to show clients the establishment's sanitation practices", "Protects the establishment from fines by demonstrating any sanitation violation was the client's fault"], options_es: ["Proporciona evidencia de que los protocolos de saneamiento requeridos se están siguiendo de manera consistente — los inspectores pueden revisar los registros para verificar el cumplimiento de los procedimientos de desinfección, los registros de uso de productos y la capacitación del personal, en lugar de depender únicamente de la observación durante la inspección", "La documentación solo se requiere para instalaciones médicas — los establecimientos de estética están exentos de los requisitos de documentación de TDLR", "Sirve solo como material de marketing para mostrar a los clientes las prácticas de saneamiento del establecimiento", "Protege al establecimiento de multas al demostrar que cualquier violación de saneamiento fue culpa del cliente"], correct: 0, explanation: "Documentation of sanitation activities (disinfectant use logs, training records, equipment maintenance records) provides verifiable compliance evidence during TDLR inspections. It shows that sanitation protocols are consistently implemented, not just performed when an inspector is present. Good documentation is an indicator of a well-managed, compliant establishment." },
  { id: 167, question: "When evaluating whether a skin condition is a contraindication for an esthetics service, the esthetician should consider:", question_es: "Al evaluar si una condición de la piel es una contraindicación para un servicio de estética, el esteticista debe considerar:", options: ["Whether the condition is contagious (could spread to the esthetician or other clients through contact or contaminated implements), whether the service could worsen the condition (heat, massage, or chemicals on compromised skin), and whether the condition is outside the esthetician's scope of practice", "Only whether the client finds the service desirable — client preference overrides all contraindications", "Only conditions diagnosed by a physician — estheticians may not recognize or respond to undiagnosed conditions as contraindications", "Only conditions that are painful to the client — cosmetic conditions are never contraindications"], options_es: ["Si la condición es contagiosa (podría propagarse al esteticista o a otros clientes a través del contacto o implementos contaminados), si el servicio podría empeorar la condición (calor, masaje o productos químicos en piel comprometida) y si la condición está fuera del alcance de práctica del esteticista", "Solo si el cliente considera el servicio deseable — la preferencia del cliente anula todas las contraindicaciones", "Solo las condiciones diagnosticadas por un médico — los esteticistas no pueden reconocer o responder a condiciones no diagnosticadas como contraindicaciones", "Solo las condiciones que son dolorosas para el cliente — las condiciones cosméticas nunca son contraindicaciones"], correct: 0, explanation: "Evaluating contraindications requires a three-part assessment: (1) Contagion risk — is the condition transmissible via the service? (2) Harm risk — would the service worsen the client's condition? (3) Scope — is treatment of this condition within esthetic scope or does it require physician involvement? All three criteria must be considered before proceeding." },
  { id: 168, question: "Products used for professional esthetics services should be stored:", question_es: "Los productos usados para los servicios profesionales de estética deben almacenarse:", options: ["According to manufacturer specifications — typically in a cool, dry location away from direct sunlight and extreme temperatures, with lids tightly closed to prevent contamination, oxidation, and degradation of active ingredients", "In a heated cabinet to keep them at body temperature for immediate client application", "In the refrigerator — all professional esthetics products require cold storage to remain effective", "Accessible to clients in open display so they can examine and select their preferred products"], options_es: ["Según las especificaciones del fabricante — típicamente en un lugar fresco y seco alejado de la luz solar directa y las temperaturas extremas, con tapas bien cerradas para evitar la contaminación, oxidación y degradación de los ingredientes activos", "En un gabinete calentado para mantenerlos a temperatura corporal para su aplicación inmediata al cliente", "En el refrigerador — todos los productos profesionales de estética requieren almacenamiento en frío para mantenerse efectivos", "Accesibles a los clientes en exhibición abierta para que puedan examinar y seleccionar sus productos preferidos"], correct: 0, explanation: "Improper product storage degrades active ingredients and can promote microbial growth. Heat, light, and air exposure oxidize and denature many esthetic product ingredients. Always follow manufacturer storage instructions. Keep products tightly closed between uses to prevent both contamination and product degradation." },
  { id: 169, question: "In an esthetics establishment, 'decontamination' of reusable implements proceeds in which correct sequence?", question_es: "En un establecimiento de estética, la 'descontaminación' de los implementos reutilizables procede en qué secuencia correcta?", options: ["(1) Pre-clean by removing visible debris, (2) wash with soap/detergent and water to remove all organic material, (3) rinse thoroughly, (4) submerge in EPA-registered disinfectant for full contact time, (5) remove, rinse if directed, dry, and store in a clean covered container", "(1) Soak in disinfectant first, (2) then clean with soap and water, (3) then store wet in the disinfectant container", "(1) Rinse in water only, (2) place in UV cabinet for 30 minutes, (3) return to the service tray for reuse", "(1) Wipe with alcohol pad, (2) allow to air dry, (3) reuse — this is the complete decontamination protocol"], options_es: ["(1) Pre-limpiar eliminando los residuos visibles, (2) lavar con jabón/detergente y agua para eliminar todo el material orgánico, (3) enjuagar a fondo, (4) sumergir en desinfectante registrado por la EPA durante el tiempo de contacto completo, (5) retirar, enjuagar si se indica, secar y almacenar en un recipiente limpio y cubierto", "(1) Remojar en desinfectante primero, (2) luego limpiar con jabón y agua, (3) luego almacenar húmedo en el recipiente del desinfectante", "(1) Enjuagar solo con agua, (2) colocar en gabinete UV durante 30 minutos, (3) regresar a la bandeja de servicio para reutilizar", "(1) Limpiar con almohadilla de alcohol, (2) dejar secar al aire, (3) reutilizar — este es el protocolo completo de descontaminación"], correct: 0, explanation: "The correct implement decontamination sequence: clean first (remove ALL organic matter with soap and water — disinfectants cannot penetrate debris), then disinfect (full contact time in EPA-registered product), then rinse and dry, then store clean. Reversing the order (disinfecting before cleaning) fails because disinfectants cannot work through organic soil." },
  { id: 170, question: "A client with an active fungal nail infection (onychomycosis) seeking nail care services at a Texas esthetics establishment:", question_es: "Un cliente con una infección fúngica activa de las uñas (onicomicosis) que busca servicios de cuidado de uñas en un establecimiento de estética de Texas:", options: ["Should not receive nail services in the affected area — onychomycosis is a contraindication because the infection can spread to other nails or clients through contaminated implements, and treatment of nail fungal infections is outside esthetics scope of practice", "Can receive nail polish application only — topical polish creates a barrier that prevents spread", "Should receive extra buffing and filing to remove infected nail tissue during the service", "Must be treated with antifungal nail products available in any esthetics establishment before receiving nail services"], options_es: ["No debe recibir servicios de uñas en el área afectada — la onicomicosis es una contraindicación porque la infección puede propagarse a otras uñas o clientes a través de implementos contaminados, y el tratamiento de las infecciones fúngicas de las uñas está fuera del alcance de la práctica de estética", "Solo puede recibir aplicación de esmalte de uñas — el esmalte tópico crea una barrera que previene la propagación", "Debe recibir limado y raspado adicional para eliminar el tejido de uñas infectado durante el servicio", "Debe tratarse con productos antimicóticos para uñas disponibles en cualquier establecimiento de estética antes de recibir servicios de uñas"], correct: 0, explanation: "Onychomycosis (nail fungus) is contagious. Filing and buffing infected nails creates debris that can contaminate implements and surrounding surfaces. Treatment of onychomycosis requires prescription antifungal medication (topical or oral) — this is outside esthetics scope. Clients with active nail fungus should be referred to a physician and services declined for affected nails." },
  { id: 171, question: "Which of the following is an example of 'indirect contact' transmission of pathogens in an esthetics setting?", question_es: "¿Cuál de los siguientes es un ejemplo de transmisión de patógenos por 'contacto indirecto' en un entorno de estética?", options: ["A client develops a skin infection from a bacterial pathogen deposited on a facial brush by a previous client — the pathogen survived on the implement and was transferred to the new client during their service", "An esthetician directly touches an infected client's lesion and immediately touches a second client's skin", "A client inhales respiratory droplets expelled by the esthetician during a service", "A pathogen enters the client's skin through a cut made by a lancet during extraction"], options_es: ["Un cliente desarrolla una infección cutánea por un patógeno bacteriano depositado en un cepillo facial por un cliente anterior — el patógeno sobrevivió en el implemento y fue transferido al nuevo cliente durante su servicio", "Un esteticista toca directamente la lesión infectada de un cliente e inmediatamente toca la piel de un segundo cliente", "Un cliente inhala gotitas respiratorias expulsadas por el esteticista durante un servicio", "Un patógeno entra a la piel del cliente a través de un corte hecho por una lanceta durante la extracción"], correct: 0, explanation: "Indirect contact transmission occurs when pathogens travel from a source to a susceptible host through an intermediate object (fomite) — in this case, a contaminated implement. This is the most common infection transmission route in esthetics. Proper implement disinfection between clients is the primary defense against indirect contact transmission." },
  { id: 172, question: "Why must an esthetics establishment maintain a logbook documenting implement disinfection procedures?", question_es: "¿Por qué debe un establecimiento de estética mantener un libro de registro que documente los procedimientos de desinfección de implementos?", options: ["A disinfection log provides evidence of consistent compliance with sanitation protocols — it protects the establishment during TDLR inspections, demonstrates due diligence if a client claims they received an infection from the establishment, and reinforces staff accountability for proper procedures", "Logbooks are only required for surgical centers — esthetics establishments have no legal requirement to document disinfection", "Logbooks only document product purchases, not procedures — TDLR only reviews financial records", "A logbook is kept only to track product inventory, not sanitation compliance"], options_es: ["Un registro de desinfección proporciona evidencia del cumplimiento consistente con los protocolos de saneamiento — protege al establecimiento durante las inspecciones de TDLR, demuestra la debida diligencia si un cliente afirma que recibió una infección del establecimiento y refuerza la responsabilidad del personal por los procedimientos adecuados", "Los libros de registro solo son requeridos para los centros quirúrgicos — los establecimientos de estética no tienen ningún requisito legal de documentar la desinfección", "Los libros de registro solo documentan las compras de productos, no los procedimientos — TDLR solo revisa los registros financieros", "Un libro de registro se mantiene solo para rastrear el inventario de productos, no el cumplimiento de saneamiento"], correct: 0, explanation: "Documentation of sanitation activities is a best practice and may be required by regulatory bodies. A disinfection log: (1) creates an audit trail showing consistent compliance, (2) provides legal protection if a client alleges they were infected, (3) ensures accountability from all staff, and (4) makes pattern problems visible (e.g., a staff member consistently skipping steps)." },
  { id: 173, question: "An esthetician with an active respiratory illness (fever, productive cough) should:", question_es: "Un esteticista con una enfermedad respiratoria activa (fiebre, tos productiva) debe:", options: ["Not perform client services while symptomatic — working while sick risks transmitting the infection to clients at close facial-service range; the esthetician should stay home until fever-free for 24 hours without fever-reducing medications", "Wear a surgical mask and proceed with all services — a mask provides complete protection against transmission", "Sanitize hands more frequently during the service but otherwise proceed normally", "Notify clients by phone about the illness and let them decide whether to keep their appointments"], options_es: ["No realizar servicios al cliente mientras tiene síntomas — trabajar mientras está enfermo arriesga transmitir la infección a los clientes a corta distancia del servicio facial; el esteticista debe quedarse en casa hasta estar sin fiebre durante 24 horas sin medicamentos para reducir la fiebre", "Usar una mascarilla quirúrgica y proceder con todos los servicios — una mascarilla proporciona protección completa contra la transmisión", "Desinfectar las manos con más frecuencia durante el servicio pero proceder normalmente de lo demás", "Notificar a los clientes por teléfono sobre la enfermedad y dejarlos decidir si mantienen sus citas"], correct: 0, explanation: "An esthetician performing facial services while actively ill with a respiratory infection creates significant transmission risk given the extremely close working proximity. The accepted guideline: stay home when febrile (fever = active infection/contagiousness). While a mask reduces (but doesn't eliminate) droplet transmission, the safest course for client safety is to reschedule services." },
  { id: 174, question: "The term 'nosocomial infection' refers to an infection:", question_es: "El término 'infección nosocomial' se refiere a una infección:", options: ["Acquired in a healthcare or professional service setting — in esthetics, a 'nosocomial' type infection would be one acquired by a client from contaminated implements or surfaces in the establishment, highlighting why sanitation is a public health matter", "Only occurring in hospitals — no similar risk exists in non-hospital settings", "Caused exclusively by antibiotic-resistant bacteria", "An infection the client brought into the establishment rather than acquired there"], options_es: ["Adquirida en un entorno de atención médica o servicio profesional — en la estética, una infección de tipo 'nosocomial' sería aquella adquirida por un cliente de implementos o superficies contaminadas en el establecimiento, destacando por qué el saneamiento es un asunto de salud pública", "Solo ocurriendo en hospitales — no existe un riesgo similar en entornos que no son hospitales", "Causada exclusivamente por bacterias resistentes a los antibióticos", "Una infección que el cliente trajo al establecimiento en lugar de adquirirla allí"], correct: 0, explanation: "Nosocomial (healthcare-associated) infections are acquired in professional care settings. While the term classically refers to hospitals, the concept applies in esthetics — an infection a client develops as a result of their service is effectively a nosocomial-type infection. This framing underscores the public health significance of esthetics infection control protocols." },
  { id: 175, question: "The most effective way to prevent transmission of bloodborne pathogens in an esthetics setting when performing extractions is:", question_es: "La forma más efectiva de prevenir la transmisión de patógenos de transmisión sanguínea en un entorno de estética al realizar extracciones es:", options: ["Using single-use lancets (discard after one use), wearing gloves throughout the extraction procedure, having a sharps container immediately accessible, and properly disinfecting all reusable extraction implements after the service", "Asking clients to self-perform extractions so no blood contact occurs with the esthetician", "Using double-thick gloves — no other precaution is needed if gloves are worn", "Only performing extractions on clients who have tested negative for bloodborne pathogens within 30 days"], options_es: ["Usar lancetas de uso único (desechar después de un uso), usar guantes durante todo el procedimiento de extracción, tener un contenedor de objetos cortantes inmediatamente accesible y desinfectar adecuadamente todos los implementos de extracción reutilizables después del servicio", "Pedirles a los clientes que realicen sus propias extracciones para que no haya contacto con sangre con el esteticista", "Usar guantes de doble grosor — no se necesita ninguna otra precaución si se usan guantes", "Solo realizar extracciones en clientes que hayan dado negativo en patógenos de transmisión sanguínea dentro de los 30 días"], correct: 0, explanation: "For extractions (which may contact blood), the complete protection package: single-use lancets (never reuse, discard in sharps container immediately), gloves throughout, a nearby accessible sharps container (so no need to carry lancet across the room), and post-service disinfection of all implements. Testing clients for bloodborne pathogens is discriminatory and impractical." },
  { id: 176, question: "Proper hand hygiene timing in esthetics — when must the esthetician wash hands or use alcohol-based hand sanitizer?", question_es: "El momento adecuado de la higiene de manos en la estética — ¿cuándo debe el esteticista lavarse las manos o usar desinfectante de manos a base de alcohol?", options: ["Before putting on gloves, after removing gloves, before and after each client, after touching potentially contaminated surfaces (doorknobs, phone, used linens), after coughing/sneezing, and after using the restroom — hand hygiene at these critical moments breaks the chain of transmission", "Only after completing the full service — hand hygiene during the service interrupts workflow unnecessarily", "Only when hands are visibly dirty with product — routine hand hygiene between clients is not required", "Once at the beginning of the workday and once at the end — hand hygiene at other times is unnecessary"], options_es: ["Antes de ponerse los guantes, después de quitarse los guantes, antes y después de cada cliente, después de tocar superficies potencialmente contaminadas (pomos de puertas, teléfono, ropa de cama usada), después de toser/estornudar y después de usar el baño — la higiene de manos en estos momentos críticos rompe la cadena de transmisión", "Solo después de completar el servicio completo — la higiene de manos durante el servicio interrumpe innecesariamente el flujo de trabajo", "Solo cuando las manos están visiblemente sucias con producto — la higiene de manos rutinaria entre clientes no es requerida", "Una vez al comienzo del día de trabajo y una vez al final — la higiene de manos en otros momentos es innecesaria"], correct: 0, explanation: "WHO's 'Five Moments for Hand Hygiene' (adapted for esthetics): before client contact, before aseptic procedures, after exposure risk (blood/body fluids), after client contact, and after contact with client surroundings. Key additional moments: before gloves on, after gloves off, after touching high-touch surfaces. Gloves do not replace hand hygiene." },
  { id: 177, question: "Double-bagging contaminated waste from esthetics services means:", question_es: "La doble bolsa de los residuos contaminados de los servicios de estética significa:", options: ["Placing contaminated materials in one bag, then placing that bag into a second bag before disposal — this extra layer reduces the risk of bag tearing during disposal and contains any leakage, providing additional protection when handling potentially infectious waste", "Using two different types of bags (one plastic, one paper) for waste disposal", "Only required for medical waste — regular esthetics waste requires only single-bag disposal", "Placing all waste from two separate clients in a single bag"], options_es: ["Colocar los materiales contaminados en una bolsa, luego colocar esa bolsa en una segunda bolsa antes de la eliminación — esta capa adicional reduce el riesgo de desgarro de la bolsa durante la eliminación y contiene cualquier fuga, proporcionando protección adicional al manejar residuos potencialmente infecciosos", "Usar dos tipos diferentes de bolsas (una de plástico, una de papel) para la eliminación de residuos", "Solo requerida para residuos médicos — los residuos regulares de estética solo requieren eliminación de bolsa única", "Colocar todos los residuos de dos clientes separados en una sola bolsa"], correct: 0, explanation: "Double-bagging provides an additional containment layer for waste that may contain blood or body fluids. It reduces the risk of bag failure during transport and disposal. While not always required for routine esthetics waste, it is a best practice for any waste that is visibly contaminated with blood or other potentially infectious materials." },
  { id: 178, question: "In Texas, an esthetics license holder who violates TDLR sanitation rules may face:", question_es: "En Texas, un titular de licencia de estética que viole las reglas de saneamiento de TDLR puede enfrentar:", options: ["Administrative penalties including fines, license suspension, or license revocation — TDLR has authority to take disciplinary action against license holders who fail to comply with sanitation requirements under Texas Occupations Code Chapter 1603 and Texas Admin Code Chapter 83", "Only verbal warnings — TDLR has no authority to penalize license holders for sanitation violations", "Only civil lawsuits from injured clients — the state cannot take action against esthetics license holders", "No penalties — sanitation rules are voluntary guidelines without enforcement authority"], options_es: ["Sanciones administrativas que incluyen multas, suspensión de licencia o revocación de licencia — TDLR tiene autoridad para tomar medidas disciplinarias contra los titulares de licencias que no cumplan con los requisitos de saneamiento bajo el Capítulo 1603 del Código de Ocupaciones de Texas y el Capítulo 83 del Código Administrativo de Texas", "Solo advertencias verbales — TDLR no tiene autoridad para penalizar a los titulares de licencias por violaciones de saneamiento", "Solo demandas civiles de clientes lesionados — el estado no puede tomar medidas contra los titulares de licencias de estética", "Sin penalidades — las reglas de saneamiento son pautas voluntarias sin autoridad de aplicación"], correct: 0, explanation: "TDLR has full enforcement authority under Texas Occupations Code Ch. 1603 and Texas Admin Code Ch. 83. Violations can result in: administrative penalties (fines), license suspension, and in serious cases, license revocation. TDLR inspects establishments and can issue Citations for sanitation violations. Repeated or serious violations receive escalating penalties." },
  { id: 179, question: "An esthetics student or new licensee performing services under supervision must follow the same infection control protocols as licensed estheticians because:", question_es: "Un estudiante de estética o nuevo licenciado que realiza servicios bajo supervisión debe seguir los mismos protocolos de control de infecciones que los esteticistas licenciados porque:", options: ["Sanitation and infection control requirements apply to all persons providing esthetics services in Texas — the supervisory relationship does not exempt the student or new licensee from TDLR sanitation compliance, and clients receive the same protection regardless of who performs the service", "Students and new licensees are exempt from sanitation requirements while under direct supervision", "Sanitation requirements only apply to the establishment owner, not to individual service providers", "Students in a licensed school are under different TDLR rules that allow reduced sanitation standards during training"], options_es: ["Los requisitos de saneamiento y control de infecciones se aplican a todas las personas que proporcionan servicios de estética en Texas — la relación de supervisión no exime al estudiante o nuevo licenciado del cumplimiento de saneamiento de TDLR, y los clientes reciben la misma protección independientemente de quién realice el servicio", "Los estudiantes y los nuevos licenciados están exentos de los requisitos de saneamiento mientras están bajo supervisión directa", "Los requisitos de saneamiento solo aplican al propietario del establecimiento, no a los proveedores de servicios individuales", "Los estudiantes en una escuela licenciada están bajo diferentes reglas de TDLR que permiten estándares de saneamiento reducidos durante el entrenamiento"], correct: 0, explanation: "TDLR sanitation requirements apply to all persons performing esthetics services in Texas, regardless of their level of training or supervisory status. Clients receiving services from students or apprentices deserve the same protection from infection as clients served by experienced licensees. Supervisors are responsible for ensuring their supervisees follow all required protocols." },
  { id: 180, question: "When purchasing disinfectant products for an esthetics establishment, the esthetician should verify:", question_es: "Al comprar productos desinfectantes para un establecimiento de estética, el esteticista debe verificar:", options: ["That the product has an EPA registration number, is labeled for use in cosmetology/esthetics settings, has the specific claims needed (bactericidal, virucidal, fungicidal) for the implements being disinfected, and that the label directions are feasible for the establishment's workflow", "Only the price — all disinfectants are equally effective regardless of brand or EPA registration", "That the product is the strongest concentration available — higher concentration always equals better disinfection", "Only that the product has a pleasant fragrance — this indicates high-quality formulation"], options_es: ["Que el producto tiene un número de registro de la EPA, está etiquetado para uso en entornos de cosmetología/estética, tiene las reclamaciones específicas necesarias (bactericida, viricida, fungicida) para los implementos que se desinfectan y que las instrucciones de la etiqueta son factibles para el flujo de trabajo del establecimiento", "Solo el precio — todos los desinfectantes son igualmente efectivos independientemente de la marca o el registro de la EPA", "Que el producto es la concentración más fuerte disponible — una concentración más alta siempre equivale a una mejor desinfección", "Solo que el producto tiene una fragancia agradable — esto indica una formulación de alta calidad"], correct: 0, explanation: "Selecting the right disinfectant requires: (1) EPA registration (government-verified claims), (2) appropriate label claims for the pathogens of concern (bactericidal, virucidal, fungicidal as needed), (3) labeled for use on the surfaces/implements in question, (4) concentration/contact time that's practical to implement. Higher concentration doesn't always mean better — some products work at lower concentrations." },
  { id: 181, question: "The 'wet sanitation method' for implements in esthetics (soaking in liquid disinfectant) is preferred over dry methods because:", question_es: "El 'método de saneamiento húmedo' para implementos en la estética (remojo en desinfectante líquido) es preferido sobre los métodos secos porque:", options: ["Liquid submersion ensures that all surfaces of an implement — including crevices, joints, and inner surfaces — are in contact with the disinfectant for the required contact time, providing more reliable coverage than spray or wipe methods alone", "Wet methods are required because all esthetics implements are waterproof and can withstand liquid submersion", "Dry disinfection methods are actually preferred — wet immersion damages implements", "Wet and dry methods are equally effective for all implement types — choice is based only on convenience"], options_es: ["La inmersión en líquido garantiza que todas las superficies de un implemento — incluidas las grietas, las juntas y las superficies internas — estén en contacto con el desinfectante durante el tiempo de contacto requerido, proporcionando una cobertura más confiable que los métodos de spray o limpieza solos", "Los métodos húmedos son requeridos porque todos los implementos de estética son impermeables y pueden soportar la inmersión en líquido", "Los métodos de desinfección secos son en realidad preferidos — la inmersión húmeda daña los implementos", "Los métodos húmedos y secos son igualmente efectivos para todos los tipos de implementos — la elección se basa solo en la conveniencia"], correct: 0, explanation: "Wet immersion (submersion) in liquid disinfectant ensures complete coverage of all implement surfaces including recesses and joints where pathogens can hide. Spray-and-wipe methods may miss these areas and require very precise technique to achieve adequate contact time. For non-porous implements (metal tools), wet immersion is the most reliable disinfection method." },
  { id: 182, question: "A 'sharps injury log' as required by OSHA for establishments with bloodborne pathogen exposure risk must document:", question_es: "Un 'registro de lesiones por objetos cortantes' según lo requerido por OSHA para establecimientos con riesgo de exposición a patógenos de transmisión sanguínea debe documentar:", options: ["The date and time of the injury, the type and brand of device involved, the department/work area, an explanation of how the incident occurred, and the job classification of the injured employee — this information is used to identify prevention opportunities", "Only the name of the injured employee and the date of injury", "Only injuries that resulted in a diagnosed bloodborne pathogen infection — near-misses are not documented", "Financial costs associated with each injury — OSHA primarily uses this data for insurance purposes"], options_es: ["La fecha y hora de la lesión, el tipo y la marca del dispositivo involucrado, el departamento/área de trabajo, una explicación de cómo ocurrió el incidente y la clasificación laboral del empleado lesionado — esta información se utiliza para identificar oportunidades de prevención", "Solo el nombre del empleado lesionado y la fecha de la lesión", "Solo las lesiones que resultaron en una infección de patógenos de transmisión sanguínea diagnosticada — los casi-accidentes no se documentan", "Los costos financieros asociados con cada lesión — OSHA utiliza principalmente estos datos con fines de seguro"], correct: 0, explanation: "OSHA requires a sharps injury log (part of the exposure control plan) for tracking needlestick and sharp object injuries. Required elements: date of injury, type/brand/model of device, location of incident, description of how the injury occurred, and job classification. This data enables facilities to identify high-risk devices and procedures and prioritize prevention efforts." },
  { id: 183, question: "To protect esthetics clients from infection when performing eyebrow shaping with tweezers:", question_es: "Para proteger a los clientes de estética de infecciones al realizar el modelado de cejas con pinzas:", options: ["Use properly disinfected tweezers for each client, avoid tweezing over broken or irritated skin, and use a fresh cotton pad with antiseptic to cleanse the area before and after the service — never use the same tweezers on different clients without proper disinfection", "Wipe tweezers with a dry tissue between clients — this removes visible hair debris and is sufficient", "Tweezing does not require any special infection control — the skin is not broken by tweezing", "Use the client's own personal tweezers for the service to eliminate cross-contamination risk"], options_es: ["Usar pinzas correctamente desinfectadas para cada cliente, evitar pinzar sobre piel rota o irritada y usar una almohadilla de algodón fresca con antiséptico para limpiar el área antes y después del servicio — nunca usar las mismas pinzas en diferentes clientes sin la desinfección adecuada", "Limpiar las pinzas con un pañuelo seco entre clientes — esto elimina los residuos de cabello visible y es suficiente", "La depilación con pinzas no requiere ningún control especial de infecciones — la piel no se rompe con la depilación", "Usar las pinzas personales del propio cliente para el servicio para eliminar el riesgo de contaminación cruzada"], correct: 0, explanation: "Tweezing, while usually not breaking the skin, contacts the skin surface closely and removes hair from follicles — creating micro-trauma that can introduce pathogens if implements are not clean. Properly disinfected tweezers for each client, along with pre/post antiseptic cleansing of the eyebrow area, are required sanitation practices." },
  { id: 184, question: "What does it mean when an EPA-registered disinfectant label states it is 'effective against MRSA'?", question_es: "¿Qué significa cuando la etiqueta de un desinfectante registrado por la EPA indica que es 'efectivo contra el MRSA'?", options: ["The product has been tested and shown to kill Methicillin-resistant Staphylococcus aureus (MRSA) at the stated dilution and contact time — MRSA is a particularly resistant strain of Staph aureus relevant to esthetics given its ability to cause serious skin infections", "MRSA is a mold — the claim means the product prevents mold growth on surfaces", "The product is effective against all antibiotic-resistant organisms when used in any concentration", "MRSA claims are only relevant for hospital use — the claim has no significance in esthetics settings"], options_es: ["El producto ha sido probado y demostrado que mata Staphylococcus aureus resistente a la meticilina (MRSA) en la dilución y el tiempo de contacto indicados — el MRSA es una cepa particularmente resistente de Staph aureus relevante para la estética dada su capacidad para causar infecciones cutáneas graves", "El MRSA es un moho — la reclamación significa que el producto previene el crecimiento de moho en las superficies", "El producto es efectivo contra todos los organismos resistentes a los antibióticos cuando se usa en cualquier concentración", "Las reclamaciones de MRSA solo son relevantes para uso hospitalario — la reclamación no tiene significado en los entornos de estética"], correct: 0, explanation: "MRSA (Methicillin-resistant Staphylococcus aureus) is a significant skin pathogen in community settings — it causes boils, wound infections, and can spread in close-contact environments. A disinfectant with an MRSA kill claim has been EPA-tested against this organism. This claim is relevant to esthetics because staph skin infections can be introduced or spread in esthetics establishments." },
]

const NS = [
  { id: 185, question: "The nail plate is primarily composed of:", question_es: "La placa ungueal está compuesta principalmente de:", options: ["Hardened keratin — the same fibrous protein that forms hair and the outer layer of skin, but in the nail plate the keratin is highly cross-linked and compressed into a hard, translucent structure", "Bone — the nail plate is an extension of the finger's distal phalanx", "Calcium deposits — nails are made of the same mineral as bones and teeth", "Collagen — the nail's structural protein is the same as the skin's dermis"], options_es: ["Queratina endurecida — la misma proteína fibrosa que forma el cabello y la capa exterior de la piel, pero en la placa ungueal la queratina está altamente entrecruzada y comprimida en una estructura dura y translúcida", "Hueso — la placa ungueal es una extensión de la falange distal del dedo", "Depósitos de calcio — las uñas están hechas del mismo mineral que los huesos y los dientes", "Colágeno — la proteína estructural de la uña es la misma que la dermis de la piel"], correct: 0, explanation: "Nails are composed primarily of hard (onychogenic) keratin — a fibrous protein that is also the main structural component of hair and the stratum corneum of the epidermis. Nail keratin is more densely cross-linked than hair keratin, giving nails their characteristic hardness. Nails contain very little calcium — the 'nails need calcium' belief is a common misconception." },
  { id: 186, question: "The nail matrix is the structure responsible for:", question_es: "La matriz ungueal es la estructura responsable de:", options: ["Nail growth — it is the living tissue beneath the proximal nail fold where nail cells (onychocytes) are produced and pushed forward to form the nail plate; any damage to the matrix can permanently affect nail growth or shape", "Attaching the nail plate to the nail bed below", "Producing the cuticle (eponychium) that seals the nail fold", "Providing blood supply to the nail through a direct capillary network in the nail plate"], options_es: ["El crecimiento de las uñas — es el tejido vivo debajo del pliegue ungueal proximal donde se producen las células ungueales (onicitos) y se empujan hacia adelante para formar la placa ungueal; cualquier daño a la matriz puede afectar permanentemente el crecimiento o la forma de la uña", "Unir la placa ungueal al lecho ungueal debajo", "Producir la cutícula (eponiquio) que sella el pliegue ungueal", "Proporcionar suministro de sangre a la uña a través de una red capilar directa en la placa ungueal"], correct: 0, explanation: "The nail matrix contains the germinal cells that produce the nail plate. Located under the proximal nail fold (and visible as the lunula at the nail's base), it is the most important functional structure of the nail apparatus. Trauma to the matrix (cuts, crushing injuries) can result in nail ridging, pitting, or permanent nail deformity." },
  { id: 187, question: "The lunula of the nail is:", question_es: "La lúnula de la uña es:", options: ["The whitish, half-moon shaped area at the base of the nail plate — it represents the visible portion of the nail matrix and appears lighter because the matrix tissue beneath is thicker and less transparent than the nail bed farther forward", "The thin skin seal between the nail plate and the nail fold — it prevents bacteria from entering beneath the nail", "The area at the nail's tip where it separates from the nail bed — called the hyponychium zone", "The groove on each side of the nail plate that guides nail growth direction"], options_es: ["El área blanquecina en forma de media luna en la base de la placa ungueal — representa la porción visible de la matriz ungueal y parece más clara porque el tejido de la matriz debajo es más grueso y menos transparente que el lecho ungueal más adelante", "El sello de piel delgada entre la placa ungueal y el pliegue ungueal — evita que las bacterias entren por debajo de la uña", "El área en la punta de la uña donde se separa del lecho ungueal — llamada zona hiponiquio", "El surco en cada lado de la placa ungueal que guía la dirección del crecimiento de la uña"], correct: 0, explanation: "The lunula (Latin for 'little moon') is the visible, crescent-shaped white area at the proximal end of the nail plate. It represents the distal end of the nail matrix. Its white appearance is due to the thicker, more opaque matrix tissue beneath — it hasn't yet fully keratinized and bonded to the nail bed. It is most visible on the thumb." },
  { id: 188, question: "The eponychium (cuticle) serves which protective function for the nail?", question_es: "El eponiquio (cutícula) sirve cuál función protectora para la uña?", options: ["It forms a waterproof seal at the junction of the nail plate and the proximal nail fold — preventing bacteria, fungi, and debris from entering the space beneath the nail fold and infecting the nail matrix", "It nourishes the nail plate by transferring nutrients from the dermal blood supply directly to the nail plate surface", "It produces new nail plate cells to replace those lost at the free edge", "It anchors the nail plate to the nail bed through fibrous attachments"], options_es: ["Forma un sello impermeable en la unión de la placa ungueal y el pliegue ungueal proximal — evitando que bacterias, hongos y residuos entren en el espacio debajo del pliegue ungueal e infecten la matriz ungueal", "Nutre la placa ungueal transfiriendo nutrientes del suministro sanguíneo dérmico directamente a la superficie de la placa ungueal", "Produce nuevas células de la placa ungueal para reemplazar las perdidas en el borde libre", "Ancla la placa ungueal al lecho ungueal a través de fijaciones fibrosas"], correct: 0, explanation: "The eponychium (visible cuticle) is a thin layer of epidermis that grows onto the surface of the nail plate from the proximal nail fold. It seals the space between the nail plate and the nail fold, acting as a waterproof barrier that prevents microorganism infiltration to the sensitive nail matrix. Cutting or aggressively pushing back the cuticle removes this protective seal." },
  { id: 189, question: "The hyponychium is located:", question_es: "El hiponiquio se localiza:", options: ["Under the free edge of the nail — it is the epithelial tissue that seals the distal end of the nail bed, preventing pathogens from entering beneath the nail plate at its free edge", "Above the nail plate, forming the skin visible at the base of the nail", "On the lateral sides of the nail, forming the nail walls", "In the nail matrix, producing the nail plate's lower layers"], options_es: ["Debajo del borde libre de la uña — es el tejido epitelial que sella el extremo distal del lecho ungueal, evitando que los patógenos entren por debajo de la placa ungueal en su borde libre", "Encima de la placa ungueal, formando la piel visible en la base de la uña", "En los lados laterales de la uña, formando las paredes de la uña", "En la matriz ungueal, produciendo las capas inferiores de la placa ungueal"], correct: 0, explanation: "The hyponychium is the epidermis under the free edge of the nail plate, where the nail separates from the nail bed. It forms a seal that protects against bacteria and fungi entering beneath the nail. Damage to the hyponychium during aggressive nail services can create an entry point for pathogens and cause discomfort or infection." },
  { id: 190, question: "The nail bed is the tissue that:", question_es: "El lecho ungueal es el tejido que:", options: ["Lies directly beneath the nail plate and is firmly adhered to it — it is supplied with blood vessels giving the nail plate its characteristic pink color, and it provides support and nourishment to the overlying nail plate", "Produces the nail plate — it is the most active growth area of the nail", "Seals the sides of the nail plate to the surrounding skin", "Is the white visible area at the base of the nail plate"], options_es: ["Yace directamente debajo de la placa ungueal y está firmemente adherido a ella — está provisto de vasos sanguíneos que le dan a la placa ungueal su característico color rosado, y proporciona soporte y nutrición a la placa ungueal suprayacente", "Produce la placa ungueal — es el área de crecimiento más activa de la uña", "Sella los lados de la placa ungueal a la piel circundante", "Es el área blanca visible en la base de la placa ungueal"], correct: 0, explanation: "The nail bed extends from the lunula to the hyponychium and adheres to the underside of the nail plate. Its rich blood supply (dermal papillae) gives nails their pink hue. Nail bed disorders (fungal infection, separation, trauma) disrupt the nail plate's color and adherence. The nail bed does not produce nail cells — that is the matrix's function." },
  { id: 191, question: "The nail grooves and nail walls (lateral nail folds) serve which structural purpose?", question_es: "Los surcos ungueales y las paredes ungueales (pliegues ungueales laterales) sirven cuál propósito estructural?", options: ["They form channels on either side of the nail plate that guide nail plate growth in a straight direction — the nail walls are the raised folds of skin on each side of the nail that cover the nail grooves", "They are the areas where nail growth originates — equivalent to the nail matrix for lateral growth", "They produce the lateral cuticle that seals the sides of the nail plate", "They anchor the nail to the bone of the distal phalanx through ligament attachments"], options_es: ["Forman canales en cada lado de la placa ungueal que guían el crecimiento de la placa ungueal en una dirección recta — las paredes ungueales son los pliegues de piel elevados en cada lado de la uña que cubren los surcos ungueales", "Son las áreas donde origina el crecimiento de las uñas — equivalente a la matriz ungueal para el crecimiento lateral", "Producen la cutícula lateral que sella los lados de la placa ungueal", "Anclan la uña al hueso de la falange distal a través de fijaciones ligamentosas"], correct: 0, explanation: "Nail grooves (sulci) are the channels on each side of the nail plate. The nail walls (lateral nail folds) are the folds of skin that flank these grooves and guide nail plate growth. Improper nail shaping that cuts into the lateral grooves or curls the nail plate edges can cause ingrown nails and discomfort or infection." },
  { id: 192, question: "The average rate of fingernail growth in a healthy adult is approximately:", question_es: "La tasa promedio de crecimiento de las uñas de los dedos en un adulto sano es aproximadamente:", options: ["3–4 millimeters per month (about 1/8 inch per month) — growth rate varies by digit (thumbs grow fastest among toenails; middle finger fastest among fingernails), age, health, nutrition, and season (faster in summer)", "3–4 centimeters per month — nails grow rapidly under normal conditions", "1 millimeter per year — nail growth is extremely slow", "10 millimeters per week — nails grow at the same rate as hair"], options_es: ["3–4 milímetros por mes (aproximadamente 1/8 de pulgada por mes) — la tasa de crecimiento varía según el dígito (los pulgares crecen más rápido entre las uñas de los pies; el dedo medio más rápido entre las uñas de los dedos), la edad, la salud, la nutrición y la temporada (más rápido en verano)", "3–4 centímetros por mes — las uñas crecen rápidamente en condiciones normales", "1 milímetro por año — el crecimiento de las uñas es extremadamente lento", "10 milímetros por semana — las uñas crecen al mismo ritmo que el cabello"], correct: 0, explanation: "Fingernails grow approximately 3–4 mm per month (toenails about 1.5 mm/month). Growth rates vary: dominant hand grows faster; middle finger fastest; nails grow faster in summer, during pregnancy, and in youth. Growth slows with age, poor nutrition (especially protein/biotin deficiency), circulatory disease, and illness." },
  { id: 193, question: "Onychorrhexis is a nail condition characterized by:", question_es: "La onicorrexis es una condición ungueal caracterizada por:", options: ["Brittle nails with longitudinal ridges and a tendency to split or break at the free edge — often caused by excessive exposure to water or chemicals, improper nail care, nutritional deficiencies, or systemic health conditions", "Abnormal thickening of the nail plate — nails grow unusually thick and opaque", "Separation of the nail plate from the nail bed starting at the free edge", "Nail biting that has removed the free edge and damaged the proximal nail fold"], options_es: ["Uñas quebradizas con estrías longitudinales y tendencia a partirse o romperse en el borde libre — a menudo causadas por exposición excesiva al agua o químicos, cuidado inadecuado de las uñas, deficiencias nutricionales o condiciones de salud sistémicas", "Engrosamiento anormal de la placa ungueal — las uñas crecen inusualmente gruesas y opacas", "Separación de la placa ungueal del lecho ungueal comenzando en el borde libre", "Morderse las uñas que ha eliminado el borde libre y dañado el pliegue ungueal proximal"], correct: 0, explanation: "Onychorrhexis (brittle nail syndrome) presents with longitudinal ridging and nail brittleness with splitting or peeling at the free edge. Contributing factors: frequent immersion in water, exposure to harsh chemicals, acetone-based removers, nutritional deficiencies (iron, biotin), thyroid disorders, and aging. Estheticians should avoid services that further stress these fragile nails." },
  { id: 194, question: "Onychauxis refers to:", question_es: "La onicauxis se refiere a:", options: ["Abnormal thickening and overgrowth of the nail plate — the nail becomes thick, hard, and may become yellowish or brownish in color; causes include trauma, fungal infection, or systemic conditions; often requires medical referral", "Abnormal thinning of the nail plate due to chemical exposure", "A condition where nails curve inward at the sides causing ingrown nails", "The normal increase in nail thickness that occurs with aging"], options_es: ["Engrosamiento anormal y sobrecrecimiento de la placa ungueal — la uña se vuelve gruesa, dura y puede volverse amarillenta o marrón en color; las causas incluyen traumatismo, infección fúngica o condiciones sistémicas; a menudo requiere derivación médica", "Adelgazamiento anormal de la placa ungueal debido a la exposición química", "Una condición donde las uñas se curvan hacia adentro en los lados causando uñas encarnadas", "El aumento normal en el grosor de la uña que ocurre con el envejecimiento"], correct: 0, explanation: "Onychauxis (hypertrophy of the nail) is abnormal nail thickening. It may result from: repeated trauma (common in toenails), fungal infection (which also causes discoloration), psoriasis, or other systemic diseases. Severely thickened nails may be difficult to service in an esthetics setting and may require a podiatrist for safe reduction." },
  { id: 195, question: "Beau's lines on the nail plate are:", question_es: "Las líneas de Beau en la placa ungueal son:", options: ["Transverse (horizontal) grooves or ridges that run across the nail plate — they indicate a temporary disruption of nail matrix activity and can result from high fever, severe illness, chemotherapy, significant nutritional deficiency, or major physiological stress", "Longitudinal (vertical) lines running from the cuticle to the free edge — a normal aging change", "White spots on the nail plate caused by minor trauma to the nail matrix", "Dark pigmented bands running lengthwise on the nail — requiring immediate physician referral"], options_es: ["Surcos o crestas transversales (horizontales) que corren a través de la placa ungueal — indican una interrupción temporal de la actividad de la matriz ungueal y pueden resultar de fiebre alta, enfermedad grave, quimioterapia, deficiencia nutricional significativa o estrés fisiológico importante", "Líneas longitudinales (verticales) que van de la cutícula al borde libre — un cambio de envejecimiento normal", "Manchas blancas en la placa ungueal causadas por trauma menor a la matriz ungueal", "Bandas pigmentadas oscuras que corren longitudinalmente en la uña — que requieren derivación inmediata al médico"], correct: 0, explanation: "Beau's lines are transverse depressions (indentations running side to side) in the nail plate. They form when matrix activity is temporarily interrupted by illness, fever, surgery, or metabolic stress. The nail stops growing for a period, creating a groove that grows out with the nail. Their position on the nail can indicate when the stress event occurred." },
  { id: 196, question: "Leukonychia (white spots on the nail) is most commonly caused by:", question_es: "La leuconiquia (manchas blancas en las uñas) es más comúnmente causada por:", options: ["Minor trauma to the nail matrix during the nail's growth phase — contrary to popular belief, white spots are not caused by calcium or zinc deficiency; they represent air pockets within the nail plate from incomplete keratinization after trauma", "Calcium deficiency — the white spots appear where the nail lacks calcium", "Fungal infection of the nail — all white nail changes indicate onychomycosis", "Zinc deficiency — leukonychia is always a nutritional deficiency sign"], options_es: ["Trauma menor a la matriz ungueal durante la fase de crecimiento de la uña — al contrario de la creencia popular, las manchas blancas no son causadas por deficiencia de calcio o zinc; representan bolsas de aire dentro de la placa ungueal por queratinización incompleta después del trauma", "Deficiencia de calcio — las manchas blancas aparecen donde a la uña le falta calcio", "Infección fúngica de la uña — todos los cambios de uñas blancas indican onicomicosis", "Deficiencia de zinc — la leuconiquia es siempre un signo de deficiencia nutricional"], correct: 0, explanation: "True leukonychia (white spots within the nail plate) is caused by minor trauma to the nail matrix — bumping the nail, aggressive cuticle manipulation, or other trauma during the matrix's growth phase. The trauma causes incomplete keratinization, leaving air pockets that appear white. Despite popular myth, white spots are not caused by nutritional deficiencies." },
  { id: 197, question: "Paronychia in an esthetics nail care context is:", question_es: "La paroniquia en el contexto del cuidado de uñas en estética es:", options: ["An infection (bacterial or fungal) of the skin surrounding the nail (the paronychium/nail fold area) — it presents as redness, swelling, pain, and sometimes pus at the nail fold; active paronychia is a contraindication for nail services, requiring medical treatment", "A condition where the nail plate separates from the nail bed — also called onycholysis", "Longitudinal ridging of the nail caused by nutritional deficiency", "The normal appearance of healthy nail fold skin — no treatment is required"], options_es: ["Una infección (bacteriana o fúngica) de la piel que rodea la uña (el área del paroniquio/pliegue ungueal) — se presenta como enrojecimiento, hinchazón, dolor y a veces pus en el pliegue ungueal; la paroniquia activa es una contraindicación para los servicios de uñas, que requiere tratamiento médico", "Una condición donde la placa ungueal se separa del lecho ungueal — también llamada onicólisis", "Estrías longitudinales de la uña causadas por deficiencia nutricional", "La apariencia normal de la piel del pliegue ungueal saludable — no se requiere tratamiento"], correct: 0, explanation: "Paronychia is an infection of the periungual tissues (nail fold skin). Acute paronychia (usually bacterial — Staphylococcus aureus) causes rapid-onset redness, throbbing pain, and pus. Chronic paronychia (usually fungal — Candida) develops slowly with swelling and nail fold changes. Both types are contraindications for nail services." },
  { id: 198, question: "Onycholysis is the separation of the nail plate from the nail bed and may be caused by:", question_es: "La onicólisis es la separación de la placa ungueal del lecho ungueal y puede ser causada por:", options: ["Trauma, fungal infection, psoriasis, thyroid disorders, or reaction to certain nail products — the separated area appears white or yellow and is a pathway for bacteria and fungi to establish sub-nail infections; esthetic nail services should avoid the affected area", "Only trauma — onycholysis never has non-traumatic causes", "Excessive polish application — nail polish always causes nail plate separation over time", "Dehydration — drinking more water resolves onycholysis without any other treatment"], options_es: ["Trauma, infección fúngica, psoriasis, trastornos tiroideos o reacción a ciertos productos de uñas — el área separada parece blanca o amarilla y es una vía para que las bacterias y los hongos establezcan infecciones sub-ungueales; los servicios de uñas estéticos deben evitar el área afectada", "Solo trauma — la onicólisis nunca tiene causas no traumáticas", "Aplicación excesiva de esmalte — el esmalte de uñas siempre causa separación de la placa ungueal con el tiempo", "Deshidratación — beber más agua resuelve la onicólisis sin ningún otro tratamiento"], correct: 0, explanation: "Onycholysis (nail plate separation from nail bed) has multiple causes: trauma (most common), fungal infection, psoriasis (particularly affects nails), thyroid disease, iron deficiency, and reaction to nail products (especially photosensitizing products in photoonycholysis). The separated area becomes colonized by bacteria/fungi. Services should avoid the separated area." },
  { id: 199, question: "In assessing nail health during a client consultation for nail care services, the esthetician should observe:", question_es: "Al evaluar la salud de las uñas durante una consulta al cliente para servicios de cuidado de uñas, el esteticista debe observar:", options: ["Nail plate color (pink, yellow, brown, white changes), surface texture (smooth, ridged, pitted), shape (normal, curved, spoon-shaped), thickness, nail fold integrity (any redness, swelling, pus), and the condition of the surrounding skin", "Only the length of the nail plate — shape and color are aesthetic concerns not relevant to service safety", "Only whether the client has previous nail polish applied — no other nail assessment is necessary", "Only the client's preferred nail shape for the service"], options_es: ["Color de la placa ungueal (cambios de rosa, amarillo, marrón, blanco), textura superficial (suave, estriada, picada), forma (normal, curvada, en forma de cuchara), grosor, integridad del pliegue ungueal (cualquier enrojecimiento, hinchazón, pus) y la condición de la piel circundante", "Solo la longitud de la placa ungueal — la forma y el color son preocupaciones estéticas no relevantes para la seguridad del servicio", "Solo si el cliente tiene esmalte de uñas previo aplicado — no se necesita ninguna otra evaluación de uñas", "Solo la forma de uña preferida del cliente para el servicio"], correct: 0, explanation: "A thorough nail assessment before service identifies contraindications (infection, fungus, separation, paronychia) and informs appropriate service modifications. Observe: color (discoloration may indicate fungus, systemic disease, or melanoma), texture (ridging, pitting from psoriasis), shape abnormalities, nail fold health, and skin condition. Abnormal findings may require referral before service." },
  { id: 200, question: "Koilonychia (spoon nails), where the nail plate becomes concave and scooped rather than curved, is associated with:", question_es: "La coiloniquia (uñas en cuchara), donde la placa ungueal se vuelve cóncava y ahuecada en lugar de curvada, está asociada con:", options: ["Iron deficiency anemia — koilonychia can be a visible sign of systemic iron deficiency and warrants referral to a physician; it may also occur from occupational exposure to petroleum solvents or as a genetic trait", "Excessive nail polish application — the chemical weight flattens the nail plate over time", "Onychomycosis (fungal nail infection) — fungi cause the nail to cup inward", "Nail biting — the concavity results from mechanical trauma to the free edge"], options_es: ["Anemia por deficiencia de hierro — la coiloniquia puede ser un signo visible de deficiencia sistémica de hierro y amerita derivación a un médico; también puede ocurrir por exposición ocupacional a solventes de petróleo o como rasgo genético", "Aplicación excesiva de esmalte de uñas — el peso químico aplana la placa ungueal con el tiempo", "Onicomicosis (infección fúngica de las uñas) — los hongos hacen que la uña se curve hacia adentro", "Morderse las uñas — la concavidad resulta del trauma mecánico en el borde libre"], correct: 0, explanation: "Koilonychia (spoon nail) presents as a nail plate that has lost its normal transverse curvature and become flat or concave (like a spoon). The classic association is iron-deficiency anemia, though it can also be a normal finding in infants, result from occupational chemical exposure, or be hereditary. Estheticians observing this should recommend physician evaluation." },
]

let out = readFileSync(FILE, 'utf8')
const nsSection = '\n  // ─── NAIL STRUCTURE & ANALYSIS (ids 185–215) ────────────────────────────────\n'
out += IC.map(q => fmt(q, icT, icTes, icPt, icPtes)).join('\n') + '\n'
out += nsSection
out += NS.map(q => fmt(q, nsT, nsTes, nsPt, nsPtes)).join('\n') + '\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${IC.length} Infection Control (ids ${IC[0].id}–${IC[IC.length-1].id}) + ${NS.length} Nail Structure (ids ${NS[0].id}–${NS[NS.length-1].id})`)
